package dev.agentforge.invoices.extract;

import java.io.IOException;

import org.apache.pdfbox.Loader;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.text.PDFTextStripper;

/**
 * Pulls the text layer out of a PDF. Invoices generated by software (most of them) have one.
 * A scanned paper invoice is just an image inside a PDF and gives back (almost) no text:
 * those need a vision model, which is the next step.
 */
public final class PdfText {

    /** Fewer characters than this means there's no real text layer. */
    static final int MIN_TEXT_LENGTH = 30;

    public static String extract(byte[] pdf) throws IOException {
        try (PDDocument document = Loader.loadPDF(pdf)) {
            PDFTextStripper stripper = new PDFTextStripper();
            stripper.setSortByPosition(true); // keeps table columns on the same line
            return stripper.getText(document).strip();
        }
    }

    public static boolean hasTextLayer(String text) {
        return text.replaceAll("\\s+", "").length() >= MIN_TEXT_LENGTH;
    }

    private PdfText() {
    }
}
